'use strict';
/**
 * The Topology map's saved node positions, as a corpus generated by RUNNING the
 * live `src/topologyLayout.js`.
 *
 * That module exists for one reason, stated in its own header: "this is the one
 * place where caller-supplied strings become OBJECT KEYS in a file written to
 * disk, so it needs direct test coverage rather than only being exercised
 * through a running server."
 *
 * ---- WHAT MAKES IT WORTH A GENERATOR RATHER THAN A READING ------------------
 *
 * Two things a Go port gets wrong by writing what the code appears to say.
 *
 * 1. REJECTION IS TOTAL, NOT PER-KEY. One banned key, one malformed key, one
 *    non-finite coordinate and the WHOLE MAP returns null — and null means 400,
 *    not "no positions". A port that skipped the bad entry would persist a
 *    partial layout and report success.
 *
 * 2. `toFixed(1)` IS NOT Go's `%.1f`. JavaScript rounds a decimal-halfway value
 *    by the binary double nearest it; Go's strconv rounds half to EVEN. They
 *    disagree on inputs like 0.25 and 2.5, and a coordinate that differs in the
 *    first decimal moves a node on the map. The corpus carries halfway values on
 *    purpose so the difference is measured rather than assumed.
 *
 * Prototype pollution has no Go analogue, but the KEY RULES still do: a `..` or
 * a `/` in a key would reach a persisted file, and the live side refuses them.
 *
 *   MIKRODASH_SRC=../MikroDash node tools/topology-layout-cases.js          # write
 *   MIKRODASH_SRC=../MikroDash node tools/topology-layout-cases.js --check  # fail if stale
 */

const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');

const ROOT = path.join(__dirname, '..');
const LIVE = path.resolve(process.env.MIKRODASH_SRC || path.join(ROOT, '..', 'MikroDash'));
const mod = require(path.join(LIVE, 'src', 'topologyLayout.js'));
const { cleanPositions, isValidRouterId, MAX_NODES, COORD_LIMIT } = mod;
assert.equal(typeof cleanPositions, 'function', 'topologyLayout.js no longer exports cleanPositions');

const P = (o) => o;
const many = (n) => {
  const out = {};
  for (let i = 0; i < n; i++) out['aa:bb:cc:dd:ee:' + String(i).padStart(2, '0')] = { x: i, y: i };
  return out;
};

const CASES = [
  ['an ordinary map', P({ '48:A9:8A:E5:CE:34': { x: 10, y: 20 } })],
  ['two nodes', P({ 'a:1': { x: 1, y: 2 }, 'b:2': { x: 3, y: 4 } })],
  ['the id fallback key', P({ 'id:abc*3': { x: 1, y: 1 } })],
  ['an empty map', P({})],

  // ---- REJECTION IS TOTAL -------------------------------------------------
  // BUILT WITH JSON.parse, NOT AN OBJECT LITERAL. `{ __proto__: … }` SETS THE
  // PROTOTYPE rather than creating a key, so the literal form has no own
  // `__proto__` at all — it serialises to `{}` and the corpus would record the
  // live module refusing an EMPTY MAP, which it does not. `JSON.parse` creates a
  // real own property, and is also how the value actually arrives: as a parsed
  // request body.
  ['__proto__ as a key', JSON.parse('{"__proto__":{"x":1,"y":1}}')],
  ['constructor as a key', P({ constructor: { x: 1, y: 1 } })],
  ['prototype as a key', P({ prototype: { x: 1, y: 1 } })],
  ['one good key and one banned', P({ 'a:1': { x: 1, y: 1 }, constructor: { x: 2, y: 2 } })],
  ['a traversal key', P({ '../etc/passwd': { x: 1, y: 1 } })],
  ['a slash in a key', P({ 'a/b': { x: 1, y: 1 } })],
  ['a space in a key', P({ 'a b': { x: 1, y: 1 } })],
  ['an empty key', P({ '': { x: 1, y: 1 } })],
  ['a 65-character key', P({ ['a'.repeat(65)]: { x: 1, y: 1 } })],
  ['a 64-character key', P({ ['a'.repeat(64)]: { x: 1, y: 1 } })],

  // ---- SHAPES -------------------------------------------------------------
  ['null', null],
  ['an array', []],
  ['a string', 'nope'],
  ['a number', 5],
  ['a value that is not an object', P({ 'a:1': 5 })],
  ['a value that is an array', P({ 'a:1': [1, 2] })],
  ['a value that is null', P({ 'a:1': null })],
  ['a missing y', P({ 'a:1': { x: 1 } })],
  ['a NaN coordinate', P({ 'a:1': { x: NaN, y: 1 } })],
  ['an Infinite coordinate', P({ 'a:1': { x: Infinity, y: 1 } })],
  ['a non-numeric string coordinate', P({ 'a:1': { x: 'left', y: 1 } })],
  // `Number('12')` is 12, so a numeric STRING is accepted — a port using a
  // type switch would reject it.
  ['a numeric string coordinate', P({ 'a:1': { x: '12', y: '13.5' } })],
  ['a boolean coordinate', P({ 'a:1': { x: true, y: 1 } })],

  // ---- LIMITS -------------------------------------------------------------
  ['exactly MAX_NODES', many(MAX_NODES)],
  ['one over MAX_NODES', many(MAX_NODES + 1)],
  ['beyond the coordinate limit', P({ 'a:1': { x: COORD_LIMIT + 1000, y: -COORD_LIMIT - 1000 } })],
  ['at the coordinate limit', P({ 'a:1': { x: COORD_LIMIT, y: -COORD_LIMIT } })],

  // ---- ROUNDING, where JS and Go disagree ---------------------------------
  ['a halfway value 0.25', P({ 'a:1': { x: 0.25, y: -0.25 } })],
  ['a halfway value 2.5', P({ 'a:1': { x: 2.5, y: -2.5 } })],
  ['a halfway value 0.05', P({ 'a:1': { x: 0.05, y: -0.05 } })],
  ['a halfway value 0.15', P({ 'a:1': { x: 0.15, y: -0.15 } })],
  ['a halfway value 1.05', P({ 'a:1': { x: 1.05, y: -1.05 } })],
  ['already one decimal', P({ 'a:1': { x: 1.1, y: -1.1 } })],
  ['many decimals', P({ 'a:1': { x: 1.23456789, y: -9.87654321 } })],
  ['a negative zero', P({ 'a:1': { x: -0.01, y: 0 } })],
];

const cases = CASES.map(([name, raw]) => {
  const got = cleanPositions(raw);
  return {
    name,
    // The input, carried as JSON so the Go side receives exactly what the live
    // side was handed. `__proto__` survives JSON.stringify as an ordinary key,
    // which is the point: it is a KEY here, not a prototype.
    input: JSON.stringify(raw),
    // null is a REFUSAL (a 400), not an empty map.
    want: got === null ? null : Object.fromEntries(Object.entries(got)),
  };
});

const routerIDs = ['r1', 'a-b_c', 'A'.repeat(64), 'A'.repeat(65), '', 'a/b', '../x', 'a b', 'a.b']
  .map((rid) => ({ rid, ok: isValidRouterId(rid) }));

// ---- BELIEVABILITY --------------------------------------------------------
{
  const refused = cases.filter((c) => c.want === null).length;
  assert.ok(refused >= 15, 'only ' + refused + ' cases were refused — the rejection paths are ' +
    'not being exercised, and a port that accepted everything would pass');
  assert.ok(cases.filter((c) => c.want !== null).length >= 8,
    'almost everything was refused — a port that refused everything would pass');

  // THE TOTAL-REJECTION RULE must be visible: a map with one good key and one
  // banned key must be refused OUTRIGHT, not reduced to the good one.
  // The `__proto__` case must carry a REAL key, or it is a test of `{}`.
  const proto = cases.find((c) => c.name === '__proto__ as a key');
  assert.ok(proto.input.includes('__proto__'),
    'the __proto__ case serialised to ' + proto.input + ' — an object literal set the prototype ' +
    'instead of creating a key, so nothing here tests a banned key');
  assert.equal(proto.want, null, 'a map with a __proto__ key was not refused');

  const mixed = cases.find((c) => c.name === 'one good key and one banned');
  assert.equal(mixed.want, null,
    'a map with one banned key was not refused outright — then nothing here distinguishes ' +
    'rejecting the map from skipping the entry');

  // And the rounding must actually round.
  const q = cases.find((c) => c.name === 'many decimals').want['a:1'];
  assert.equal(q.x, 1.2, 'the coordinate was not rounded to one decimal');
  assert.ok(routerIDs.some((r) => r.ok) && routerIDs.some((r) => !r.ok),
    'the router-id corpus does not discriminate');
}

const FILE = path.join(ROOT, 'testdata', 'topology-layout-cases.json');
const text = JSON.stringify({ maxNodes: MAX_NODES, coordLimit: COORD_LIMIT, cases, routerIDs },
  null, 2) + '\n';
if (process.argv.includes('--check')) {
  const have = fs.existsSync(FILE) ? fs.readFileSync(FILE, 'utf8') : '';
  if (have !== text) {
    console.error('topology-layout-cases: STALE — regenerate with ' +
      '`node tools/topology-layout-cases.js`');
    process.exit(1);
  }
  console.log('topology-layout-cases: ' + cases.length + ' cases current');
} else {
  fs.writeFileSync(FILE, text);
  console.log('topology-layout-cases: wrote ' + cases.length + ' cases, ' +
    cases.filter((c) => c.want === null).length + ' refused');
}
